/* Sponsor. Every value the theme may touch comes from a token; the plate and
 * the slot sizes deliberately do not, and the reason is written beside them.
 *
 * BDS-043: the slot is never re-coloured. Specimen 4g draws the four lockups
 * and design/twins/4g.json measures ours against them. This file sets the
 * label's type, the lockup's arrangement and the plate the logo sits on, and
 * it sets nothing at all inside the logo: no fill, no filter, no border. */

.gs-sponsor {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
}

/* The line that says this is a sponsor. Quieter than the game and never
   absent: a logo with nothing above it is an advert nobody was told about.
   The drawing sets it in the eyebrow: DM Sans 700, tracked and capitalised. */
.gs-sponsor__label {
  flex: none;
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  letter-spacing: var(--gs-type-eyebrow-letter-spacing);
  text-transform: var(--gs-type-eyebrow-text-transform);
  color: var(--gs-color-ink-secondary);
}

/* The plate, and the size box on it.
 *
 * Literal pixels on purpose, and literal colours on purpose. A token is a theme
 * axis, and BDS-043 says this slot is not on any theme axis: the arcade theme
 * must not make a sponsor's mark larger than the stadium theme does, and no
 * theme may put it on a gradient. The drawing writes the rule beside the
 * lockups ("plate: auto|light|dark", "logo never tinted, never on gradient",
 * "min plate padding 8") and draws every logo on a white plate. These are the
 * sizes and radii specimen 4g draws, and they change when the drawing changes. */
.gs-sponsor__logo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  padding: 0 8px;
  box-sizing: border-box;
}

.gs-sponsor__logo--light { background: white; }
.gs-sponsor__logo--dark { background: black; }

.gs-sponsor__logo > * {
  display: block;
  width: auto;
  height: 100%;
  max-width: 100%;
}

.gs-sponsor--inline .gs-sponsor__logo { height: 28px; border-radius: 6px; }
.gs-sponsor--hud .gs-sponsor__logo { height: 32px; border-radius: 999px; }
.gs-sponsor--reward .gs-sponsor__logo { height: 22px; border-radius: 5px; }
.gs-sponsor--interstitial .gs-sponsor__logo { height: 56px; border-radius: 10px; }
.gs-sponsor--badge .gs-sponsor__logo { height: 16px; border-radius: 4px; }

/* Inline is the presented-by line: centred in the row the host gives it. */
.gs-sponsor--inline { justify-content: center; }

/* HUD attaches to a timer or score chip, so it sits tighter. */
.gs-sponsor--hud { gap: var(--gs-space-2); }

/* Reward sits inside a prize card, the line above the plate, the plate above
   the prize name the card draws. */
.gs-sponsor--reward {
  flex-direction: column;
  align-items: flex-start;
  gap: var(--gs-space-1);
}

/* The interstitial is the one lockup that owns its whole surface, so it stacks,
   centres, and draws the surface: the scrim inside the card's edge, as the
   drawing has it between rounds. */
.gs-sponsor--interstitial {
  position: relative;
  flex-direction: column;
  justify-content: center;
  /* space.3 above and below is what lands the drawing's 150px frame around the
     label, the 56px plate and the countdown line. */
  padding: var(--gs-space-3) var(--gs-space-4);
  text-align: center;
  background: var(--gs-color-scrim);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
}

.gs-sponsor__name {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  color: var(--gs-color-ink);
}

/* What the host puts under the lockup: the interstitial's countdown line. The
   host's own markup inside, so only the line's type is set here. */
.gs-sponsor__detail {
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  color: var(--gs-color-muted);
}

/* Present in the accessible name, not on screen, when the logo carries the
   brand visually. */
.gs-sponsor__name--hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}
